mapper.select:
SELECT 
  FROM CUSTOMER_INQUIRY inquiry

 WHERE inquiry.USR_SN = #{userSn}
   AND inquiry.CST_INQ_USE_YN = 'Y'

   AND inquiry.CST_INQ_STATUS_CD = #{statusCode}

 ORDER BY inquiry.CST_INQ_REG_DT DESC, inquiry.CST_INQ_SN DESC
 LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
  FROM CUSTOMER_INQUIRY
 WHERE USR_SN = #{userSn}
   AND CST_INQ_USE_YN = 'Y'

   AND CST_INQ_STATUS_CD = #{statusCode}

SELECT FROM CUSTOMER_INQUIRY inquiry
WHERE inquiry.CST_INQ_USE_YN = 'Y'
AND inquiry.CST_INQ_STATUS_CD = #{statusCode}
AND inquiry.CST_INQ_TYPE_CD = #{inquiryTypeCode}
AND ( CAST(inquiry.CST_INQ_SN AS CHAR) LIKE CONCAT('%', #{keyword}, '%') OR CAST(inquiry.USR_SN AS CHAR) LIKE CONCAT('%', #{keyword}, '%') OR inquiry.CST_INQ_TTL LIKE CONCAT('%', #{keyword}, '%') OR type_code.CMM_NM LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY CASE inquiry.CST_INQ_STATUS_CD WHEN 'INQC0007' THEN 0 WHEN 'INQC0008' THEN 1 WHEN 'INQC0009' THEN 2 ELSE 3 END ASC, inquiry.CST_INQ_REG_DT DESC, inquiry.CST_INQ_SN DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM CUSTOMER_INQUIRY inquiry JOIN CMM_CODE type_code ON type_code.CMM_CD = inquiry.CST_INQ_TYPE_CD WHERE inquiry.CST_INQ_USE_YN = 'Y'
AND inquiry.CST_INQ_STATUS_CD = #{statusCode}
AND inquiry.CST_INQ_TYPE_CD = #{inquiryTypeCode}
AND ( CAST(inquiry.CST_INQ_SN AS CHAR) LIKE CONCAT('%', #{keyword}, '%') OR CAST(inquiry.USR_SN AS CHAR) LIKE CONCAT('%', #{keyword}, '%') OR inquiry.CST_INQ_TTL LIKE CONCAT('%', #{keyword}, '%') OR type_code.CMM_NM LIKE CONCAT('%', #{keyword}, '%') )
